source "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"

_choice_command() {
    if [[ "$ARGC_CWORD" != \\* ]]; then
        return 0
    fi
    _argc_util_cache 300 _choice_command_uncached
}

_choice_command_uncached() {
    usql -X -c '\?' 2>/dev/null | gawk '
        /^[[:space:]]+\\/ {
            line = $0
            sub(/^[[:space:]]+/, "", line)
            if (match(line, /^\\[A-Za-z?!][A-Za-z0-9]*/)) {
                print substr(line, RSTART, RLENGTH)
            }
        }
    '
}

_choice_connection_name() {
    local config="${argc_config:-${XDG_CONFIG_HOME:-$HOME/.config}/usql/config.yaml}"
    if [[ ! -f "$config" ]]; then
        return 0
    fi
    gawk '
        /^[^[:space:]#][^:]*:/ {
            in_connections = ($0 ~ /^connections:[[:space:]]*$/)
            next
        }
        in_connections && /^[[:space:]]+[^#[:space:]][^:]*:/ {
            name = $0
            sub(/^[[:space:]]+/, "", name)
            sub(/:.*/, "", name)
            gsub(/^["\047]|["\047]$/, "", name)
            print name
        }
    ' "$config"
}

_choice_cset() {
    _argc_util_mode_kv =
    if [[ -n "$argc__kv_prefix" ]]; then
        _choice_driver_scheme
        _argc_util_comp_path "filter=$argc__kv_filter"
