}

_choice_driver_scheme() {
    _argc_util_cache 300 _choice_driver_scheme_uncached
}

_choice_driver_scheme_uncached() {
    usql -X -c '\drivers' 2>/dev/null | gawk '
        /^[[:space:]]+[a-z0-9_]+([[:space:]]|$)/ {
            print $1 "://"
            if (match($0, /\[[^]]*\]/)) {
                count = split(substr($0, RSTART + 1, RLENGTH - 2), aliases, /,[[:space:]]*/)
                for (i = 1; i <= count; i++) {
                    if (aliases[i] != "") {
                        print aliases[i] "://"
                    }
                }
            }
        }
    ' | _argc_util_transform nospace
}

_choice_dsn() {
    _choice_connection_name
